public class HeaderParser {

    private int parseEndOfLine(String headerPart, int end) {
        int i = end;
        while (i < headerPart.length() && headerPart.charAt(i) != '\r') {
            i++;
        }
        if (i < headerPart.length() && headerPart.charAt(i) == '\r') {
            i++;
            if (i < headerPart.length() && headerPart.charAt(i) == '\n') {
                return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        HeaderParser parser = new HeaderParser();
        String headerPart = "This is a header line\r\n";
        int end = headerPart.length() - 1;
