public class GraphGenerator {

    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        if (resultMap == null || resultMap.isEmpty()) {
            throw new IllegalArgumentException("Result map cannot be null or empty");
        }

        int numVertices = resultMap.size();
        int numEdges = numVertices * numVertices;

        for (String key : resultMap.keySet()) {
            V vertex = resultMap.get(key);
            target.addVertex(vertex);
        }

        for (int i = 0; i < numVertices; i++) {
            for (int j = i + 1; j < numVertices; j++) {
                V vertex1 = resultMap.get(String.valueOf(i));
                V vertex2 = resultMap.get(String.valueOf(j));
                target.addEdge(vertex1, vertex2);
            }
        }
    }
}

