public class TimeRangeBuilder {

    private static final long FETCH_DATA_DURATION = 10000; // Example duration in milliseconds

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        long currentStart = start;
        long currentEnd = start;

        while (currentStart < end) {
            if (currentEnd + FETCH_DATA_DURATION > end) {
                currentEnd = end;
            }
            timeRanges.add(new TimeRange(currentStart, currentEnd));
            currentStart += FETCH_DATA_DURATION;
            currentEnd += FETCH_DATA_DURATION;
        }

        return timeRanges;
    }

    public static void main(String[] args) {
        TimeRangeBuilder builder = new TimeRangeBuilder();
        List<TimeRange> timeRanges = builder.buildTimeRanges(0, 100000);
        for (TimeRange range : timeRanges) {
            System.out.println("Start: " + range.getStart() + ", End: " + range.getEnd());
        }
    }
}

