import java.util.Stack;

public class StackOperations {
    private Stack<String> outputFrameStack;

    public StackOperations() {
        outputFrameStack = new Stack<>();
    }

    /** 
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        int numArgs = 0;
        if (descriptor.startsWith("(")) {
            int i = descriptor.indexOf(')');
            if (i != -1) {
                numArgs = descriptor.length() - i - 1;
            }
        }
        for (int i = 0; i < numArgs; i++) {
            outputFrameStack.pop();
        }
    }

    public static void main(String[] args) {
        StackOperations stackOps = new StackOperations();
        stackOps.outputFrameStack.push("int");
        stackOps.outputFrameStack.push("double");
        stackOps.outputFrameStack.push("String");

        System.out.println("Before popping: " + stackOps.outputFrameStack);
        stackOps.pop("()V");
        System.out.println("After popping: " + stackOps.outputFrameStack);
    }
}

import java.io.IOException;

public class ByteArrayOutputStream {
    private byte[] buffer;
    private int size;

    public ByteArrayOutputStream() {
        this.buffer = new byte[1024];
        this.size = 0;
    }

    public void write(final byte b[], final int off, final int len) throws IOException {
        if (b == null) {
            throw new NullPointerException("The byte array cannot be null");
        }
        if (off < 0 || len < 0 || off + len > b.length) {
            throw new IndexOutOfBoundsException("Invalid offset or length");
        }
        if (size + len > buffer.length) {
            expandBuffer(size + len);
        }
        System.arraycopy(b, off, buffer, size, len);
        size += len;
    }

    private void expandBuffer(int newCapacity) {
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, size);
        buffer = newBuffer;
    }

    public byte[] toByteArray() {
        return buffer;
    }

    public int size() {
        return size;
    }
}

