public class ArrayUtils {

    /** 
     * Returns a copy of the given array of size 1 greater than the argument. The last value of the array is left to the default value.
     * @param array The array to copy, must not be <code>null</code>.
     * @param newArrayComponentType If <code>array</code> is <code>null</code>, create asize 1 array of this type.
     * @return A new copy of the array of size 1 greater than the input.
     */
    private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
        if (array == null) {
            return Array.newInstance(newArrayComponentType, 1);
        }
        final Class<?> componentType = array.getClass().getComponentType();
        final Object newArray = Array.newInstance(componentType, array.length + 1);
        System.arraycopy(array, 0, newArray, 0, array.length);
        return newArray;
    }

    public static void main(String[] args) {
        // Example usage
        Integer[] originalArray = {1, 2, 3};
        Integer[] newArray = (Integer[]) copyArrayGrow1(originalArray, Integer.class);
        System.out.println("Original array: " + java.util.Arrays.toString(originalArray));
        System.out.println("New array: " + java.util.Arrays.toString(newArray));
    }
}

