public class UnescapeId {
    /** 
     * Unescape a string DOT identifier.
     * @param input the input
     * @return the unescaped output
     */
    private String unescapeId(String input) {
        if (input == null) {
            return null;
        }
        StringBuilder result = new StringBuilder();
        boolean inEscape = false;
        for (char c : input.toCharArray()) {
            if (inEscape) {
                switch (c) {
                    case 'x':
                        result.append((char) Integer.parseInt(input.substring(result.length(), result.length() + 2), 16));
                        result.append(input.substring(result.length() + 2, result.length() + 4));
                        break;
                    default:
                        result.append(c);
                        break;
                }
                inEscape = false;
            } else if (c == '\\') {
                inEscape = true;
            } else {
                result.append(c);
            }
        }
        return result.toString();
    }

    public static void main(String[] args) {
        UnescapeId unescapeId = new UnescapeId();
        System.out.println(unescapeId.unescapeId("x123y456")); // Output: 123y456
        System.out.println(unescapeId.unescapeId("x\\x12y\\x34z")); // Output: 12y34z
        System.out.println(unescapeId.unescapeId("x\\ny\\tz")); // Output: xyzt
        System.out.println(unescapeId.unescapeId("x\\ny\\tz\\u0000")); // Output: xyzt
    }
}

